import json
n=30
g=[[0]*n for _ in range(n)]
# Existing outer 5 frame spans rows/cols 1..25.
for c in range(1,26):
    g[1][c]=g[25][c]=5
for r in range(1,26):
    g[r][1]=g[r][25]=5
# Fill the one-cell band just inside the original frame with 2.
for c in range(2,25):
    g[2][c]=g[24][c]=2
for r in range(3,24):
    g[r][2]=g[r][24]=2
# Draw the inset 5 frame, offset two cells from the original frame.
for c in range(3,24):
    g[3][c]=g[23][c]=5
for r in range(4,23):
    g[r][3]=g[r][23]=5
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))
